import React, { useState, useRef, useEffect } from 'react'
import { NavLink, useLocation, useNavigate } from 'react-router-dom';
import { DocNavItems } from '../../../Constants/docs';

const NavItem = ({ to, className, children }) => {
  const location = useLocation();
  const isActive = location.pathname === to;
  return (
    <li className={className + (isActive ? ' bdr-primary' : '')}>
      <NavLink to={to} className={`font-size14 ${(isActive ? ' fg-primary' : 'fg-text')}`}>{children}</NavLink>
    </li>
  );
};

const DocSidebar = () => {
  const [activeItem, setActiveItem] = useState(null);
  const contentRefs = useRef({});
  const location = useLocation();
  const navigate = useNavigate();

  // Find which menu section should be expanded based on current route
  useEffect(() => {
    DocNavItems.forEach((item) => {
      if (item.children) {
        const hasMatchingRoute = item.children.some(childItem => {
          if (childItem.items) {
            return childItem.items.some(subItem => subItem.to === location.pathname);
          }
          return childItem.to === location.pathname;
        });
        
        if (hasMatchingRoute) {
          setActiveItem(item.menuTitle);
        }
      }
    });
  }, [location.pathname]);

  const toggleItem = (menuTitle) => {
    setActiveItem(activeItem === menuTitle ? null : menuTitle);
  };

  const renderNavItems = (items) => {
    return items.map((item) => {
      const isExpanded = activeItem === item.menuTitle;
      const hasChildren = item.children && item.children.length > 0;
      const isActive = item.to && location.pathname === item.to;
      
      return (
        <li key={item.menuTitle} className='s-nav-item mgb8'>
          {item.to && hasChildren ? (
            // Clickable parent with children - make it a link but also allow expansion
            <div className='fxb fvc gp2 w-100p'>
              <NavLink 
                to={item.to} 
                className={`s-nav-link fxb fvc gp2 flex-grow ${isActive ? 'fg-primary' : ''}`}
              >
                <span className='s-nav-link-icon w32 h32 fxb fvc fhc bdr rds2'>
                  <i className={item.icon}></i>
                </span>
                <span className='s-nav-link-text'>
                  <span className='font-bold'>{item.menuTitle}</span>
                </span>
              </NavLink>
              <button 
                className='s-nav-link-icon mgl-auto pdl2'
                onClick={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  toggleItem(item.menuTitle);
                }}
                aria-label={`Toggle ${item.menuTitle} menu`}
                type="button"
              >
                <i className={`menu-toggle-icon pi pi-angle-down transition ${isExpanded ? 'rotate-180' : ''}`}></i>
              </button>
            </div>
          ) : item.to ? (
            // Simple clickable button without children
            <button 
              className={`s-nav-link fxb fvc fhs gp2 w-100p ${isActive ? 'fg-primary' : ''}`}
              onClick={() => navigate(item.to)}
              type="button"
            >
              {item.icon && (
                <span className='s-nav-link-icon w32 h32 fxb fvc fhc bdr rds2'>
                  <i className={item.icon}></i>
                </span>
              )}
              <span className='s-nav-link-text'>
                <span className='font-bold'>{item.menuTitle}</span>
              </span>
            </button>
          ) : (
            // Expandable button without link
            <button 
              className='s-nav-link fxb fvc gp2 w-100p'
              onClick={() => toggleItem(item.menuTitle)}
              type="button"
            >
              <span className='s-nav-link-icon w32 h32 fxb fvc fhc bdr rds2'>
                <i className={item.icon}></i>
              </span>
              <span className='s-nav-link-text'>
                <span className='font-bold'>{item.menuTitle}</span>
              </span>
              <span className='s-nav-link-icon mgl-auto'>
                <i className={`menu-toggle-icon pi pi-angle-down transition ${isExpanded ? 'rotate-180' : ''}`}></i>
              </span>
            </button>
          )}
          {item.children && (
            <div 
              className="accordion-content"
              style={{
                maxHeight: isExpanded ? `${contentRefs.current[item.menuTitle]?.scrollHeight}px` : '0',
                overflow: 'hidden',
                transition: 'max-height 0.3s ease-in-out'
              }}
              ref={el => contentRefs.current[item.menuTitle] = el}
            >
              <ol className='s-nav-list mgt2 pdl3'>
                {item.children.map((childItem) => (
                  childItem.category ? (
                    <li key={childItem.category} className='s-nav-item pdb4 pdt4'>
                      <div className='s-nav-category medium-font fg-text-secondary'>{childItem.category}</div>
                      {childItem.items && (
                        <ol className='s-nav-list mgt4'>
                          {childItem.items.map((subItem) => (
                            <NavItem
                              key={subItem.menuItem}
                              to={subItem.to}
                              className='s-nav-item bdr-l pdl10 pdt4 pdb4'
                            >
                              {subItem.menuItem}
                            </NavItem>
                          ))}
                        </ol>
                      )}
                    </li>
                  ) : (
                    <NavItem
                      key={childItem.menuItem}
                      to={childItem.to}
                      className='s-nav-item bdr-l pdl10 pdb4 pdt4'
                    >
                      {childItem.menuItem}
                    </NavItem>
                  )
                ))}
              </ol>
            </div>
          )}
        </li>
      );
    });
  };

  return (
    <>
      <aside className='ulsp-sidebar overflow-x-hidden overflow-y-auto mgb15 mgr20'>
        <nav className='sidebar-nav fxgrow'>
          <ol className='s-nav-list mgt4'>
            {renderNavItems(DocNavItems)}
          </ol>
        </nav>
      </aside>
    </>
  )
}

export default DocSidebar